parameters.jsCode:
const today = new Date();
const result = [];

for (const item of $input.all()) {
  const row = item.json;

  // Ignorer les réserves clôturées ou rejetées
  if (!row['Statut'] || row['Statut'] !== 'en_cours') continue;

  // Ignorer si pas de date de diffusion au MOEX
  const dateDiffusion = row['Date diffusion MOA au MOEX'];
  if (!dateDiffusion) continue;

  // Calculer l'ancienneté en jours
  const diffDate = new Date(dateDiffusion);
  const daysDiff = Math.floor((today - diffDate) / (1000 * 60 * 60 * 24));

  const baseData = {
    id_reserve: row['N° de réserve'],
    nom: row['Nom'],
    lot: row['N° logement'],
    piece: row['Localisation'],
    description: row['Description'],
    date_diffusion: dateDiffusion,
    nb_jours: daysDiff,
    urgence: row['Urgence'] === 'oui'
  };

  // Relance 1 : >= 7 jours ET relance_1 non encore envoyée
  if (daysDiff >= 7 && !row['Date relance 1 envoyée']) {
    result.push({
      json: { ...baseData, action: 'relance_1' }
    });
  }

  // Relance 2 : >= 14 jours ET relance_2 non encore envoyée
  if (daysDiff >= 14 && !row['Date relance 2 envoyée']) {
    result.push({
      json: { ...baseData, action: 'relance_2' }
    });
  }
}

// Si aucune action nécessaire, retourner un item vide
if (result.length === 0) {
  return [{ json: { action: 'aucune', message: 'Aucune réserve à relancer aujourd\'hui' } }];
}

return result;

